select coalesce(sum(unread_), 0)
from ujcms_conversation
where user_id_ = #{userId,jdbcType=BIGINT}

mapper.update:
update ujcms_conversation
set last_text_ = #{lastText,jdbcType=VARCHAR},
    last_time_ = #{lastTime,jdbcType=TIMESTAMP}
where id_ = #{id,jdbcType=BIGINT}

update ujcms_conversation
set unread_    = unread_ + 1,
    last_text_ = #{lastText,jdbcType=VARCHAR},
    last_time_ = #{lastTime,jdbcType=TIMESTAMP}
where id_ = #{id,jdbcType=BIGINT}

update ujcms_conversation
set unread_ = 0
where user_id_ = #{userId,jdbcType=BIGINT}
  and peer_id_ = #{peerId,jdbcType=BIGINT}
